<?php
namespace Tests\Feature;
use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\Support\AuthenticatesArchiveRequests; use Tests\TestCase;
class DepartmentTemplateMetricsApiTest extends TestCase { use RefreshDatabase, AuthenticatesArchiveRequests; public function test_it_returns_aggregate_metrics_without_record_content(): void { $this->postJson('/api/v1/metadata-templates',['name'=>'News','departmentId'=>'news','fields'=>['summary'=>'']],$this->authHeaders())->assertCreated(); $this->putJson('/api/v1/department-quality-rules',['departmentId'=>'news','requiredFields'=>['summary']],$this->authHeaders())->assertCreated(); $this->postJson('/api/v1/records/bulk',['store'=>'archive-items','records'=>[['id'=>'n1','departmentId'=>'news','title'=>'x']]],$this->authHeaders())->assertOk(); $this->getJson('/api/v1/department-template-metrics?departmentId=news',$this->authHeaders())->assertOk()->assertJsonPath('metrics.templateCount',1)->assertJsonPath('metrics.recordCount',1)->assertJsonPath('metrics.missingFieldCounts.summary',1)->assertJsonMissing(['title'=>'x']); } }
